// Shape only. No decision is made here and nothing is filtered out on
// legal grounds: the platform decides what matters. The only thing dropped
// is an inline image, which is part of the body rather than a document, and
// anything past the size ceiling, which the platform would refuse anyway.

const MAX_BYTES = 15 * 1024 * 1024;

const mail = $('Read the approved mailbox').all();
const fetched = $('Fetch the attachments').all();

const messages = mail.map((item, index) => {
  const message = item.json;
  const carried = fetched[index]?.json?.value ?? [];

  const attachments = carried
    .filter((one) => one['@odata.type'] === '#microsoft.graph.fileAttachment')
    .filter((one) => one.isInline !== true)
    .filter((one) => (one.size ?? 0) <= MAX_BYTES)
    .filter((one) => typeof one.contentBytes === 'string')
    .map((one) => ({
      filename: one.name,
      content_type: one.contentType || 'application/octet-stream',
      content_base64: one.contentBytes,
    }));

  return {
    external_id: message.id,
    mailbox: $env.LEGAL_MAILBOX,
    sender: message.from?.emailAddress?.address ?? 'unknown',
    subject: message.subject ?? '(no subject)',
    body: message.body?.content ?? message.bodyPreview ?? '',
    received_at: message.receivedDateTime,
    participants: (message.toRecipients ?? []).map((r) => ({
      name: r.emailAddress?.name,
      address: r.emailAddress?.address,
    })),
    attachments,
  };
});

return [{ json: { messages } }];

// The signature is over the exact bytes that will be sent, which is why the
// body is serialised here and handed on as a string. Serialising it again in
// the HTTP node would produce a different body and a signature that does not
// verify.
const crypto = require('crypto');
const body = JSON.stringify($json);
const signature = crypto
  .createHmac('sha256', $env.DSNLAI_WEBHOOK_SECRET)
  .update(body)
  .digest('hex');
return [{ json: { body, signature } }];
